public function handle(): void
{
    throw new \RuntimeException('Payment gateway timed out');
}

public function handle(): void
{
    $count = User::where('created_at', '>=', now()->subDay())->count();
    DB::table('reports')->insert(['date' => $this->date, 'signups' => $count]);
    Storage::disk('local')->put("reports/{$this->date}.json", json_encode(['signups' => $count]));
    Http::post('https://hooks.example.com/reports', ['signups' => $count]);
    User::where('last_login_at', '<', now()->subYear())->delete();
}

public function handle(): void
{
    Mail::raw("Thanks for your order of {$this->total}", function ($message) {
        $message->to($this->user->email)->subject('Your receipt');
    });
    Log::info('Receipt sent', ['user' => $this->user->id]);
}
